using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Xml;
using HAddon;
namespace HAddon {
 internal sealed class NativePageSnapshot {internal int DocumentId;internal string Path,Digest;internal string[] Pages,TablePages;internal DocumentParagraph[] Paragraphs;}
 internal sealed class PageScope {internal int[] Targets,Sources;}
}
class AutomaticPageUpdateTests {
 const string Xml="<HWPML><HEAD><MAPPINGTABLE><CHARSHAPELIST><CHARSHAPE Id='1' Height='1000'/></CHARSHAPELIST></MAPPINGTABLE></HEAD><BODY><SECTION><P><TEXT><TABLE><ROW><CELL><PARALIST><P><TEXT CharShape='1'><CHAR>Summary A is outdated.</CHAR></TEXT></P></PARALIST></CELL><CELL><PARALIST><P><TEXT CharShape='1'><CHAR>Summary B is outdated.</CHAR></TEXT></P></PARALIST></CELL></ROW></TABLE></TEXT></P><P><TEXT><CHAR>Detail: A is 120; B is 4.</CHAR></TEXT></P></SECTION></BODY></HWPML>";
 sealed class Env:IAutomaticPageUpdateEnvironment,IDocumentUpdateBackend,IOnDemandNativeProbe {
  internal string Current=Xml;internal int Captures,Scopes,Discoveries,Searches,Plans,Backends,Writes,SourceChecks;internal bool SourceMissing,DiscoveryUncertain,PlanStale,ScopeStale,DiscoveryStale,ExpectedStale,LocateStale,BackendStale,Unresolved,WrongTarget,MutateInputs,PartialWriteFailure,OmitParagraph,ExtraPage;internal CancellationTokenSource CancelDuringPlan;
  readonly DocumentParagraph[] paragraphs=DocumentStructure.Read(Xml);readonly string digest=TableStableSnapshot.Digest(Xml);readonly Dictionary<string,string> paths;
  readonly List<DocumentUpdateTarget> accepted=new List<DocumentUpdateTarget>();DocumentUpdateVerification verifier;
  internal Env(){paths=paragraphs.Where(p=>p.Text.StartsWith("Summary ")).ToDictionary(p=>p.Text,p=>p.Path);}
  AutomaticPageCapture Capture(){return new AutomaticPageCapture{RawXml=Xml,Snapshot=new NativePageSnapshot{DocumentId=3,Path="synthetic.hwpx",Digest=digest,Pages=ExtraPage?new[]{"Summary A is outdated. Summary B is outdated.","Detail: A is 120; B is 4.","Out of scope"}:new[]{"Summary A is outdated. Summary B is outdated.","Detail: A is 120; B is 4."},Paragraphs=OmitParagraph?paragraphs.Take(paragraphs.Length-1).ToArray():paragraphs}};}
  public Task<AutomaticPageCapture> CaptureAsync(CancellationToken token,Action<int,int> progress){Captures++;token.ThrowIfCancellationRequested();progress(1,2);progress(2,2);return Task.FromResult(Capture());}
  public Task<PageScope> ScopeAsync(AutomaticPageCapture capture,string prompt){Scopes++;if(ScopeStale)Current=Current.Replace("Detail:","Changed detail:");if(MutateInputs)capture.Snapshot.Pages[0]="mutated external";return Task.FromResult(new PageScope{Targets=new[]{1},Sources=new[]{2}});}
  public void Verify(AutomaticPageCapture c){if(c.Snapshot.Digest!=digest||TableStableSnapshot.Digest(Current)!=digest)throw new InvalidOperationException("stale");}
  public void RequireSourceEvidence(AutomaticPageCapture c,PageScope scope){SourceChecks++;if(SourceMissing)throw new InvalidOperationException("source missing");TextOnlyAutomaticPageEvidence.Validate(c,scope);if(scope.Targets.Length!=1||scope.Targets[0]!=1||scope.Sources[0]!=2||c.Snapshot.Pages[0].StartsWith("mutated"))throw new Exception("scope changed");if(MutateInputs){scope.Targets[0]=2;c.Snapshot.Digest="bad";}}
  public Task<DocumentDiscoveryResult> DiscoverAsync(AutomaticPageCapture c,PageScope scope,string prompt){Discoveries++;if(DiscoveryStale)Current=Current.Replace("Detail:","Changed detail:");var reader=new DocumentTargetDiscovery(c.Snapshot.Pages,c.Snapshot.Paragraphs,scope.Targets,scope.Sources);var payload=reader.Payload();var list=(object[])payload["paragraphs"];var ids=list.Cast<Dictionary<string,object>>().Where(p=>((string)p["text"]).StartsWith("Summary ")).Select(p=>(object)(string)p["id"]).ToArray();return Task.FromResult(reader.Validate(new Dictionary<string,object>{{"targets",ids},{"uncertainties",DiscoveryUncertain?new object[]{"ambiguous"}:new object[0]}}));}
  public OnDemandExpectedTarget[] Expected(AutomaticPageCapture c,DocumentDiscoveryTarget[] targets){if(ExpectedStale)Current=Current.Replace("Detail:","Changed detail:");var proofs=new HwpParagraphProofs(c.RawXml);return targets.Select(t=>proofs.CreateExpected(t.XmlPath)).ToArray();}
  public OnDemandLocationResult Locate(AutomaticPageCapture c,PageScope scope,OnDemandExpectedTarget[] targets,Func<bool> cancelled){if(Unresolved)return new OnDemandLocationResult{Targets=new DocumentAddressCandidate[0],Unresolved=new[]{new OnDemandUnresolvedTarget{XmlPath=targets[0].XmlPath,Reason="position unknown"}}};var result=OnDemandTargetLocator.Resolve(this,c.Snapshot.Paragraphs,targets,scope.Targets,cancelled);if(LocateStale)Current=Current.Replace("Detail:","Changed detail:");return result;}
  public Task<DocumentUpdateTarget[]> PlanAsync(AutomaticPageCapture c,PageScope scope,DocumentAddressCandidate[] targets,string prompt){Plans++;if(PlanStale)Current=Current.Replace("Detail:","Changed detail:");if(CancelDuringPlan!=null)CancelDuringPlan.Cancel();if(WrongTarget)return Task.FromResult(new[]{new DocumentUpdateTarget{Id="outside",Original="bad",Replacement="bad"}});var planner=new PageEditPlanning(c.Snapshot.Pages,targets,scope.Targets,scope.Sources,c.Snapshot.Paragraphs);var changes=targets.Select((t,i)=>(object)new Dictionary<string,object>{{"id",t.XmlPath},{"replacement",i==0?"Summary A is 120.":"Summary B is 4."},{"sourcePages",new object[]{2}}}).ToArray();return Task.FromResult(planner.Compile(new Dictionary<string,object>{{"changes",changes},{"uncertainties",new object[0]}}));}
  public IDocumentUpdateBackend CreateBackend(AutomaticPageCapture c,DocumentAddressCandidate[] targets){Backends++;if(BackendStale)Current=Current.Replace("Detail:","Changed detail:");verifier=new DocumentUpdateVerification(Xml,targets.ToDictionary(t=>t.XmlPath,t=>t.XmlPath));return this;}
  public void Prepare(string rev,DocumentUpdateTarget t){if(rev!=digest)throw new Exception("revision");verifier.ExpectedDigest(new[]{t},1);accepted.Add(new DocumentUpdateTarget{Id=t.Id,Original=t.Original,Replacement=t.Replacement});}
  public void Verify(string rev,IList<DocumentUpdateTarget> plan,int applied){verifier.Verify(Current,plan,applied);}
  public void Replace(DocumentUpdateTarget t){Writes++;var doc=new XmlDocument();doc.LoadXml(Current);var hit=doc.GetElementsByTagName("CHAR").Cast<XmlElement>().Single(e=>e.InnerText==t.Original);hit.InnerText=t.Replacement;Current=doc.OuterXml;if(PartialWriteFailure)throw new InvalidOperationException("write uncertain");}
  public void CheckSnapshot(){if(TableStableSnapshot.Digest(Current)!=digest)throw new InvalidOperationException("stale");}
  OnDemandObservedParagraph Native(string text){var p=paragraphs.Single(x=>x.Text==text);var token=new HwpParagraphProofs(Xml).CreateExpected(p.Path);int list=text.StartsWith("Summary A")?2:3;return new OnDemandObservedParagraph{List=list,Paragraph=0,Start=0,End=text.Length,Text=text,FirstPhysicalPage=1,LastPhysicalPage=1,ContainerToken=token.ContainerToken,StyleToken=token.StyleToken,StructureToken=token.StructureToken,TextVerified=true,ContainerVerified=true,StyleVerified=true,StructureVerified=true,PhysicalPageVerified=true,WholeParagraph=true};}
  public OnDemandAnchorSearch FindAnchor(string text){Searches++;return new OnDemandAnchorSearch{Complete=true,Matches=new[]{Native(text)}};}
  public OnDemandObservedParagraph InspectParagraph(int list,int para){return Native(list==2?"Summary A is outdated.":"Summary B is outdated.");}
 }
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void Reject(Func<Task> run,string message){try{run().GetAwaiter().GetResult();}catch(InvalidOperationException e){if(e.Message.Contains(message))return;throw;}throw new Exception("expected "+message);}
 static void Main(){
  var env=new Env();var flow=new AutomaticPageUpdate();var result=flow.RunAsync(env,"Update page 1 from page 2",CancellationToken.None,null).GetAwaiter().GetResult();Check(result.Applied&&result.ChangedCount==2&&env.Discoveries==1&&env.Searches==2&&env.Plans==1&&env.Writes==2&&env.SourceChecks==1,"normal end-to-end update and one immutable source proof");Check(env.Current.Contains("Detail: A is 120; B is 4.")&&env.Current.Contains("Summary A is 120.")&&env.Current.Contains("Summary B is 4."),"target and source contents");
  env=new Env{SourceMissing=true};flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(env,"update",CancellationToken.None,null),"source missing");Check(env.Discoveries==0&&env.Writes==0,"source evidence before model and writes");
  env=new Env{OmitParagraph=true};flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(env,"update",CancellationToken.None,null),"일부 문단");Check(env.Discoveries==0&&env.Writes==0,"do not send truncated structural context");
  env=new Env{ExtraPage=true};flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(env,"update",CancellationToken.None,null),"전체");Check(env.Discoveries==0&&env.Writes==0,"do not send document outside authorized ranges");
  env=new Env{DiscoveryUncertain=true};flow=new AutomaticPageUpdate();result=flow.RunAsync(env,"update",CancellationToken.None,null).GetAwaiter().GetResult();Check(result.Uncertainties.Length==1&&!result.Applied&&env.Searches==0&&env.Plans==0&&env.Writes==0,"uncertain discovery");
  env=new Env{Unresolved=true};flow=new AutomaticPageUpdate();result=flow.RunAsync(env,"update",CancellationToken.None,null).GetAwaiter().GetResult();Check(result.Uncertainties.Length==1&&env.Plans==0&&env.Writes==0,"unresolved position");
  env=new Env{PlanStale=true};flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(env,"update",CancellationToken.None,null),"stale");Check(env.Backends==0&&env.Writes==0,"changed while planning");
  foreach(var stale in new[]{new Env{ScopeStale=true},new Env{DiscoveryStale=true},new Env{ExpectedStale=true},new Env{LocateStale=true},new Env{BackendStale=true}}){flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(stale,"update",CancellationToken.None,null),"stale");Check(stale.Writes==0,"coordinator retains revision checks around every model/native boundary and before first write");}
  env=new Env{WrongTarget=true};flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(env,"update",CancellationToken.None,null),"범위");Check(env.Backends==0&&env.Writes==0,"no out-of-scope backend");
  env=new Env{MutateInputs=true};flow=new AutomaticPageUpdate();result=flow.RunAsync(env,"update",CancellationToken.None,null).GetAwaiter().GetResult();Check(result.ChangedCount==2,"environment cannot mutate pinned snapshot or scope");
  var cancel=new CancellationTokenSource();env=new Env{CancelDuringPlan=cancel};flow=new AutomaticPageUpdate();bool stopped=false;try{flow.RunAsync(env,"update",cancel.Token,null).GetAwaiter().GetResult();}catch(OperationCanceledException){stopped=true;}Check(stopped&&env.Backends==0&&env.Writes==0,"cancel before write");
  foreach(string stage in new[]{"read","scope","discover","locate","plan"}){env=new Env();flow=new AutomaticPageUpdate();cancel=new CancellationTokenSource();stopped=false;try{flow.RunAsync(env,"update",cancel.Token,delegate(string next,int done,int total){if(next==stage)cancel.Cancel();}).GetAwaiter().GetResult();}catch(OperationCanceledException){stopped=true;}Check(stopped&&env.Backends==0&&env.Writes==0,"cancel on progress "+stage);Check(stage!="read"||env.Captures==0,"cancel before native capture");Check(stage!="scope"||env.Scopes==0,"cancel before scope model");Check(stage!="discover"||env.Discoveries==0,"cancel before discovery model");Check(stage!="locate"||env.Searches==0,"cancel before native search");Check(stage!="plan"||env.Plans==0,"cancel before planning model");}
  env=new Env();flow=new AutomaticPageUpdate();cancel=new CancellationTokenSource();stopped=false;try{flow.RunAsync(env,"update",cancel.Token,delegate(string stage,int done,int total){if(stage=="apply"&&done==0)cancel.Cancel();}).GetAwaiter().GetResult();}catch(OperationCanceledException){stopped=true;}Check(stopped&&env.Backends==1&&env.Writes==0,"initial apply notification precedes any native write and respects cancellation");
  env=new Env{PartialWriteFailure=true};flow=new AutomaticPageUpdate();Reject(()=>flow.RunAsync(env,"update",CancellationToken.None,null),"write uncertain");Check(env.Writes==1&&flow.Transaction.RequiresReview&&flow.Transaction.AppliedCount==0,"uncertain first native write");
  Console.WriteLine("PASS automatic page flow: actual discovery/locator/transaction/verifier with synthetic native and model boundaries");
 }
}
